def AlphaNum_NumAlpha(s):
    alphabet = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm',
                'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']
    alphabetnums = {chr(97+i): str(i+1) for i in range(26)}
    numalpha = {str(i+1): chr(97+i) for i in range(26)}
    numalpha['26'] = 'z'
    numalpha['1'] = 'a'

    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isalpha():
            num = alphabetnums[s[i]]
            result.append(num)
            i += 1
        else:
            j = i
            while j < n and s[j].isdigit():
                j += 1
            num_str = s[i:j]
            if num_str in numalpha:
                result.append(numalpha[num_str])
            else:
                result.append(num_str)
            i = j
    return ''.join(result)
